TEST_CASE("resume issues NO L2C store when the engine has no L2C (default)")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  auto s = rv64_state(0x80001000, 0);
  s.flags |= HYBRID_FLAG_L2C;                     // producer had an L2C ...
  s.l2c.reg[HYBRID_L2C_OFF_CONTROL / 8] = 0x1;

  hybrid::ResumeDriver driver(bus, kScratch);
  // ... but set_l2c is NOT called: this engine lacks an L2C region. A store
  // there would fault the Program Buffer, so the restore must be skipped --
  // and so would the Control read-back, so no lwu may issue either.
  driver.resume(s);

  CHECK(count_progbuf_insn(bus.ops, hybrid::encode_sw(5, 6, 0)) == 0u);
  CHECK(count_progbuf_insn(bus.ops, hybrid::encode_lwu(5, 6, 0)) == 0u);
}

TEST_CASE("resume issues NO L2C store when HYBRID_FLAG_L2C is clear")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  auto s = rv64_state(0x80001000, 0);   // flag clear: block not live

  hybrid::ResumeDriver driver(bus, kScratch);
  driver.set_l2c(/*present=*/true, /*base=*/0xE0500000ull);
  driver.resume(s);

  CHECK(count_progbuf_insn(bus.ops, hybrid::encode_sw(5, 6, 0)) == 0u);
  CHECK(count_progbuf_insn(bus.ops, hybrid::encode_lwu(5, 6, 0)) == 0u);
}

TEST_CASE("resume merges Control policy bits over the target's live Control")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);
  // The target RTL's live Control: CEN=1 plus bits the hardware owns --
  // RAM-timing DRAMOCTL[11] (reset from the build config) and the read-only
  // INITSTATUS[14]. Probe-measured shape on ax66_makatau's L3C (0x801).
  bus.regfile[hybrid::regno_gpr(5)] = 0x4801ull;

  auto s = rv64_state(0x80001000, 0);
  s.flags |= HYBRID_FLAG_L2C;
  // Producer policy: CEN=1, PFTHRES=2, IPFDPT=1 -- policy bits [7:0] only;
  // the producer's RAM stub has 0 in the hardware-owned fields.
  s.l2c.reg[HYBRID_L2C_OFF_CONTROL / 8] = 0x0D;

  hybrid::ResumeDriver driver(bus, kScratch);
  driver.set_l2c(/*present=*/true, /*base=*/0xE0500000ull);
  driver.resume(s);

  // Exactly one PB lwu reads the live Control back before the store...
  CHECK(count_progbuf_insn(bus.ops, hybrid::encode_lwu(5, 6, 0)) == 1u);

  // ...and the stored value keeps the target's non-policy bits: the merge is
  // (live & ~POLICY) | (transported & POLICY) = 0x4800 | 0x0D. Storing the
  // raw transported value would zero DRAMOCTL -- the RAM-timing clobber this
  // merge exists to prevent.
  const auto d0 = find_write(bus.ops, kData0);
  bool merged_staged = false, raw_staged = false;
  for (auto v : d0) {
    if (v == 0x480Du) merged_staged = true;
    if (v == 0x000Du) raw_staged = true;
  }
  CHECK(merged_staged);
  CHECK_FALSE(raw_staged);

  // The full store set is unchanged: Control + HPM Control + Way Masks.
  CHECK(count_progbuf_insn(bus.ops, hybrid::encode_sw(5, 6, 0))
        == 2u + HYBRID_L2C_WAYMASK_NUM);
}

